const divisionSelect=document.getElementById("divisionSelect"),picSelect=document.getElementById("picSelect"),roleData=window.trackingConfig.roleData;function toggleModal(e,t){const n=document.getElementById(e);t?(n.classList.remove("hidden"),n.classList.add("flex")):(n.classList.remove("flex"),n.classList.add("hidden"))}function openEditModal(e){document.getElementById("edit_activity_name").value=e.activity_name,document.getElementById("edit_activity_date").value=e.activity_date,document.getElementById("edit_document_link").value=e.document_link,document.getElementById("edit_division").value=e.division;const t=document.getElementById("edit_pic");t.innerHTML="",roleData[e.division]&&roleData[e.division].forEach(n=>{const o=document.createElement("option");o.value=n.name,o.textContent=n.name,n.name===e.pic&&(o.selected=!0),t.appendChild(o)}),document.getElementById("form-edit").action=`/tracking-laporan/${e.id}`,toggleModal("modal-edit",!0)}function openRejectModal(e){document.getElementById("form-reject").action=`/tracking-laporan/${e}/reject`,toggleModal("modal-reject",!0)}function confirmPurpose(e){Swal.fire({title:"Purpose laporan?",text:"Laporan akan dikirim ke Sekretaris untuk approval.",icon:"info",showCancelButton:!0,confirmButtonText:"Ya",cancelButtonText:"Batal",confirmButtonColor:"#2563eb",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(t=>{t.isConfirmed&&document.getElementById(`purpose-form-${e}`).submit()})}function confirmApprove(e){Swal.fire({title:"Approve laporan?",text:"Pastikan laporan sudah sesuai.",icon:"question",showCancelButton:!0,confirmButtonText:"Approve",cancelButtonText:"Batal",confirmButtonColor:"#16a34a",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(t=>{t.isConfirmed&&document.getElementById(`approve-form-${e}`).submit()})}function confirmReject(){const e=document.getElementById("rejection_reason").value;e.trim()?Swal.fire({title:"Konfirmasi Penolakan",html:`\n            <div class="text-left">\n                <p class="mb-2">Alasan yang akan dikirim:</p>\n                <div class="bg-gray-100 p-3 rounded text-sm">\n                    ${e}\n                </div>\n            </div>\n            `,icon:"warning",showCancelButton:!0,confirmButtonText:"Ya, Tolak & Kirim",cancelButtonText:"Kembali Edit",confirmButtonColor:"#dc2626"}).then(e=>{e.isConfirmed&&document.getElementById("form-reject").submit()}):Swal.fire({icon:"warning",title:"Alasan wajib diisi"})}function confirmDelete(e){Swal.fire({title:"Hapus laporan?",text:"Data yang dihapus tidak dapat dikembalikan!",icon:"warning",showCancelButton:!0,confirmButtonColor:"#b91c1c",cancelButtonColor:"#6b7280",confirmButtonText:"Ya, Hapus!",cancelButtonText:"Batal",customClass:{popup:"rounded-[24px]",confirmButton:"rounded-xl font-bold px-4 py-2",cancelButton:"rounded-xl font-medium px-4 py-2"}}).then(t=>{t.isConfirmed&&document.getElementById(`delete-form-${e}`).submit()})}divisionSelect.addEventListener("change",function(){const e=this.value,t=roleData[e]||[];picSelect.innerHTML='<option value="" disabled selected>Pilih PIC...</option>',t.forEach(e=>{const t=document.createElement("option");t.value=e.name,t.textContent=e.name,picSelect.appendChild(t)})});